package main
import("encoding/json";"errors";"fmt";"math";"sort";"strings";"time")
type Transaction struct{ID string `json:"id"`;Date string `json:"date"`;Description string `json:"description"`;Kind string `json:"kind"`;Category string `json:"category"`;Amount float64 `json:"amount"`;Deductible bool `json:"deductible"`}
type Bracket struct{UpTo float64 `json:"upTo"`;Rate float64 `json:"rate"`}
type Config struct{Brackets []Bracket `json:"brackets"`;ReserveFloor float64 `json:"reserveFloor"`}
type Summary struct{GrossIncome float64 `json:"grossIncome"`;Expenses float64 `json:"expenses"`;DeductibleExpenses float64 `json:"deductibleExpenses"`;NonDeductibleExpenses float64 `json:"nonDeductibleExpenses"`;TaxableBase float64 `json:"taxableBase"`;TaxReserve float64 `json:"taxReserve"`;NetCash float64 `json:"netCash"`;SafeToSpend float64 `json:"safeToSpend"`;TransactionCount int `json:"transactionCount"`}
func round(v float64)float64{return math.Round(v*100)/100}
func Validate(t Transaction)error{if strings.TrimSpace(t.Description)==""{return errors.New("description is required")};if t.Kind!="income"&&t.Kind!="expense"{return errors.New("kind must be income or expense")};if t.Amount<=0||math.IsNaN(t.Amount)||math.IsInf(t.Amount,0){return errors.New("amount must be positive and finite")};if _,e:=time.Parse("2006-01-02",t.Date);e!=nil{return errors.New("date must use YYYY-MM-DD")};if t.Kind=="income"&&t.Deductible{return errors.New("income cannot be deductible")};return nil}
func Tax(base float64,bs []Bracket)(float64,error){if len(bs)==0{return 0,errors.New("configure at least one bracket")};b:=append([]Bracket(nil),bs...);sort.Slice(b,func(i,j int)bool{return b[i].UpTo<b[j].UpTo});prev,remain,total:=0.0,math.Max(0,base),0.0;for _,x:=range b{if x.Rate<0||x.Rate>1||x.UpTo<=prev{return 0,errors.New("invalid bracket thresholds or rates")};v:=math.Min(remain,x.UpTo-prev);total+=v*x.Rate;remain-=v;prev=x.UpTo};if remain>0{total+=remain*b[len(b)-1].Rate};return round(total),nil}
func Calculate(ts []Transaction,c Config)(Summary,error){s:=Summary{TransactionCount:len(ts)};for _,t:=range ts{if e:=Validate(t);e!=nil{return Summary{},fmt.Errorf("%s: %w",t.ID,e)};if t.Kind=="income"{s.GrossIncome+=t.Amount}else{s.Expenses+=t.Amount;if t.Deductible{s.DeductibleExpenses+=t.Amount}else{s.NonDeductibleExpenses+=t.Amount}}};s.TaxableBase=math.Max(0,s.GrossIncome-s.DeductibleExpenses);var e error;s.TaxReserve,e=Tax(s.TaxableBase,c.Brackets);if e!=nil{return s,e};s.GrossIncome=round(s.GrossIncome);s.Expenses=round(s.Expenses);s.DeductibleExpenses=round(s.DeductibleExpenses);s.NonDeductibleExpenses=round(s.NonDeductibleExpenses);s.TaxableBase=round(s.TaxableBase);s.NetCash=round(s.GrossIncome-s.Expenses);s.SafeToSpend=round(math.Max(0,s.NetCash-s.TaxReserve-math.Max(0,c.ReserveFloor)));return s,nil}
func Handle(action,raw string)(string,error){switch action{case "calculate","simulate":var p struct{Transactions []Transaction `json:"transactions"`;Config Config `json:"config"`};if e:=json.Unmarshal([]byte(raw),&p);e!=nil{return "",e};s,e:=Calculate(p.Transactions,p.Config);if e!=nil{return "",e};b,e:=json.Marshal(s);return string(b),e;case "validate":var t Transaction;if e:=json.Unmarshal([]byte(raw),&t);e!=nil{return "",e};if e:=Validate(t);e!=nil{return "",e};return "{\"valid\":true}",nil;default:return "",fmt.Errorf("unknown action %s",action)}}
